import assert from "node:assert/strict";
import { test } from "node:test";
import type { AcMessage } from "@os/api";
import { encode, identify, validateRemote } from "../src/protocol.js";
import { decodeWave, encodeWave } from "../src/protocols/common.js";
import { fujitsu120, fujitsu128 } from "../src/protocols/fujitsu.js";
import { panasonic216 } from "../src/protocols/panasonic.js";
import { japaneseCaptures } from "./japanese-fixtures.js";

// Expected native fields from the upstream protocol layouts; not generated by encode().
const fields: Record<
  string,
  { cool: Record<number, number>; heat: Record<number, number>; off: [number, number, number] }
> = {
  daikin280: { cool: { 21: 0x39, 22: 52 }, heat: { 21: 0x49, 22: 44 }, off: [21, 1, 0] },
  daikin2: {
    cool: { 25: 0x39, 26: 52, 6: 0x43 },
    heat: { 25: 0x49, 26: 44 },
    off: [6, 0x80, 0x80],
  },
  panasonic216: { cool: { 13: 0x31, 14: 52 }, heat: { 13: 0x41, 14: 44 }, off: [13, 1, 0] },
  mitsubishiHeavy152: { cool: { 5: 9, 7: 9 }, heat: { 5: 12, 7: 5 }, off: [5, 8, 0] },
  toshiba72: { cool: { 5: 0x90, 6: 1 }, heat: { 5: 0x50, 6: 3 }, off: [6, 7, 7] },
  toshiba80: { cool: { 5: 0x90, 6: 1 }, heat: { 5: 0x50, 6: 3 }, off: [6, 7, 7] },
  fujitsu120: { cool: { 8: 0xa1, 9: 1 }, heat: { 8: 0x61, 9: 4 }, off: [5, 255, 2] },
  fujitsu128: { cool: { 8: 0xa1, 9: 1 }, heat: { 8: 0x61, 9: 4 }, off: [5, 255, 2] },
  hitachi224: {
    cool: { 10: 0x20, 11: 0x2c, 17: 1 },
    heat: { 10: 0xc0, 11: 0x34 },
    off: [17, 1, 0],
  },
  hitachi424: {
    cool: { 11: 0x13, 13: 0x68, 25: 0x53, 27: 0xf1 },
    heat: { 13: 0x58, 25: 0x56 },
    off: [27, 0x10, 0],
  },
  sharp104: {
    cool: { 4: 0xcb, 5: 0x11, 6: 0x22, 10: 0 },
    heat: { 4: 0xc7, 5: 0x11, 6: 0x21 },
    off: [5, 0xf0, 0x20],
  },
};

for (const fixture of japaneseCaptures) {
  test(`${fixture.protocol}: identify a real capture; encode cool, heat and absolute off`, () => {
    const remote = identify(fixture.signal);
    assert.deepEqual(remote, { version: 1, protocol: fixture.protocol, state: fixture.state });
    for (const acMode of ["cool", "heat"] as const) {
      const signal = encode(remote, { acMode, temperature: acMode === "cool" ? 26 : 22 });
      const encoded = identify(signal);
      assert.equal(
        encoded.protocol,
        fixture.protocol === "toshiba80" ? "toshiba72" : fixture.protocol,
      );
      for (const [byte, expected] of Object.entries(fields[fixture.protocol]![acMode])) {
        assert.equal(encoded.state[Number(byte)], expected, `byte ${byte}`);
      }
    }
    const off = encode(remote);
    let state: number[];
    if (fixture.protocol.startsWith("fujitsu")) {
      const length = fixture.protocol === "fujitsu128" ? 7 : 6;
      state = decodeWave(
        { ...fujitsu128, sectionLengths: [length], isValidState: () => true },
        off,
      )!;
      assert.deepEqual(state, [0x14, 0x63, 0, 0x10, 0x10, 2, ...(length === 7 ? [0xfd] : [])]);
      assert.throws(() => identify(off), /temperature\/mode/); // Short off cannot be learned as a full state.
    } else {
      state = identify(off).state;
    }
    const [byte, mask, expected] = fields[fixture.protocol]!.off;
    assert.equal(state[byte]! & mask, expected);
    assert.deepEqual(remote.state, fixture.state);
    const corrupt = structuredClone(remote);
    corrupt.state[corrupt.state.length - 1]! ^= 1;
    assert.throws(() => validateRemote(corrupt));
    assert.throws(() =>
      identify({ ...fixture.signal, timings: fixture.signal.timings.slice(0, -2) }),
    );
    for (const temperature of [-1, 100, NaN, Infinity, 26.25]) {
      assert.throws(() => encode(remote, { acMode: "cool", temperature }));
    }
  });
}

const learned = (protocol: string) =>
  identify(japaneseCaptures.find((f) => f.protocol === protocol)!.signal);

test("fixed wind positions work where supported, with omitted axes retained", () => {
  const message: AcMessage = {
    acMode: "heat",
    temperature: 22,
    windDirectionVertical: "down",
    windDirectionHorizontal: "right",
  };
  const daikin = identify(encode(learned("daikin2"), message));
  assert.equal(daikin.state[17], 0xab);
  assert.equal(daikin.state[18]! & 15, 6);
  const heavy = identify(encode(learned("mitsubishiHeavy152"), message));
  assert.equal(heavy.state[11]! >> 5, 5);
  assert.equal(heavy.state[13]! & 15, 4);
  const retained = identify(encode(heavy, { acMode: "cool", temperature: 26 }));
  assert.equal(retained.state[11], heavy.state[11]);
  assert.equal(retained.state[13], heavy.state[13]);
  for (const protocol of [
    "daikin280",
    "toshiba72",
    "fujitsu120",
    "fujitsu128",
    "hitachi224",
    "hitachi424",
    "sharp104",
  ]) {
    assert.throws(() => encode(learned(protocol), message), /fixed wind/);
  }
});

test("Panasonic variant detection rejects CKP toggles and unsupported horizontal positions", () => {
  const jke = learned("panasonic216");
  assert.throws(
    () => encode(jke, { acMode: "cool", temperature: 26, windDirectionHorizontal: "left" }),
    /JKE/,
  );
  const dke = [
    2, 0x20, 0xe0, 4, 0, 0, 0, 6, 2, 0x20, 0xe0, 4, 0, 0x4f, 0x32, 0x80, 0xaf, 0x0d, 0, 6, 0x60, 0,
    0, 1, 0, 6, 0x30,
  ];
  const remote = identify(encodeWave(panasonic216, dke)); // Upstream DkeIonRealMessages.
  const result = identify(
    encode(remote, {
      acMode: "heat",
      temperature: 22,
      windDirectionHorizontal: "left",
      windDirectionVertical: "up",
    }),
  );
  assert.equal(result.state[17], 10);
  assert.equal(result.state[16], 0xa1);
  const ckp = [...dke];
  ckp[17] = 0;
  ckp[21] = 0x10;
  ckp[26] = ckp.slice(0, 26).reduce((a, b) => a + b, 0xf4) & 255;
  assert.throws(() => identify(encodeWave(panasonic216, ckp)), /Unsupported/);
});

test("Fujitsu ARREW4E temperature representation and remote ID survive learning", () => {
  // Upstream TestIRFujitsuACClass.Heat10Deg: ID 1, protocol 0x31.
  const raw = [
    0x14, 0x63, 0x10, 0x10, 0x10, 0xfe, 9, 0x31, 0x69, 0x0b, 0, 0x23, 6, 0x23, 0x20, 0xef,
  ];
  const remote = identify(encodeWave(fujitsu128, raw));
  const encoded = identify(encode(remote, { acMode: "heat", temperature: 22.5 }));
  assert.equal(encoded.state[2], 0x10);
  assert.equal(encoded.state[7], 0x31);
  assert.equal(encoded.state[8], 0x75); // ((22.5 - 8) * 2) << 2 | power.
  assert.equal(encoded.state[9], 4); // Special 10°C heat disabled.
  const off = decodeWave(
    { ...fujitsu120, sectionLengths: [7], isValidState: () => true },
    encode(remote),
  );
  assert.deepEqual(off, [0x14, 0x63, 0x10, 0x10, 0x10, 2, 0xfd]);
});
